import{_ as a,c as i,o as t,ae as o}from"./chunks/framework.CliRSA9F.js";const s="/images/social_publishing.webp",g=JSON.parse('{"title":"Social Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"features/social-publishing.md","filePath":"features/social-publishing.md"}'),n={name:"features/social-publishing.md"};function r(l,e,h,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="social-publishing" tabindex="-1">Social Publishing <a class="header-anchor" href="#social-publishing" aria-label="Permalink to &quot;Social Publishing&quot;">​</a></h1><h2 id="turn-episodes-into-short-video-clips-and-publish-them" tabindex="-1">Turn Episodes into Short Video Clips and Publish Them <a class="header-anchor" href="#turn-episodes-into-short-video-clips-and-publish-them" aria-label="Permalink to &quot;Turn Episodes into Short Video Clips and Publish Them&quot;">​</a></h2><p>Social Publishing helps you repurpose your podcast episodes into short, vertical video clips — the kind of reels that perform well on social platforms — and publish them where new listeners are most likely to discover you. Instead of editing video by hand, you let PodSEO find the strongest moments in an episode, turn them into ready-to-share clips, and post them directly to your connected social accounts.</p><p><img src="'+s+'" alt="Social Publishing Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Command Center</strong> in the sidebar, open the <strong>Planner</strong>, then select the <strong>Social Publishing</strong> tab.</p><h2 id="why-social-publishing-matters" tabindex="-1">Why Social Publishing Matters <a class="header-anchor" href="#why-social-publishing-matters" aria-label="Permalink to &quot;Why Social Publishing Matters&quot;">​</a></h2><p>Audio alone limits how far an episode can travel. Short video clips give your best moments a second life on platforms built for discovery, helping you:</p><ul><li><strong>Reach new listeners</strong> who find you through video feeds rather than podcast apps</li><li><strong>Promote new episodes</strong> with shareable highlights instead of plain links</li><li><strong>Stay consistent on social</strong> without spending hours on editing</li><li><strong>Drive traffic back to your show</strong> from the platforms your audience already uses</li></ul><p>Plan clips, captions, and channels in one place, then schedule everything from a single calendar.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Social Publishing follows a simple path: find the best moments in an episode, turn them into a video clip, then write a caption and publish the clip to your chosen platforms.</p><h3 id="step-1-find-social-clip-highlights" tabindex="-1">Step 1: Find Social Clip Highlights <a class="header-anchor" href="#step-1-find-social-clip-highlights" aria-label="Permalink to &quot;Step 1: Find Social Clip Highlights&quot;">​</a></h3><p>Start from a published episode. PodSEO reviews the episode and selects the three best moments for social clips — the segments most likely to capture attention. Before highlights are generated, you&#39;ll confirm that you have the rights or permission to create clips from the episode.</p><h3 id="step-2-review-the-moments-and-generate-video" tabindex="-1">Step 2: Review the Moments and Generate Video <a class="header-anchor" href="#step-2-review-the-moments-and-generate-video" aria-label="Permalink to &quot;Step 2: Review the Moments and Generate Video&quot;">​</a></h3><p>Once the highlights are ready, review the selected moments and choose which ones to turn into finished videos. For each clip you can adjust how the video looks — choosing a background, deciding whether to show your show cover, and toggling visual touches like a waveform — before generating the final vertical video. If a result isn&#39;t quite right, you can generate it again with different settings.</p><h3 id="step-3-create-a-social-post" tabindex="-1">Step 3: Create a Social Post <a class="header-anchor" href="#step-3-create-a-social-post" aria-label="Permalink to &quot;Step 3: Create a Social Post&quot;">​</a></h3><p>With a finished clip in hand, create a social post:</p><ol><li><strong>Attach your clip</strong> — A completed clip is required before a post can be scheduled or published.</li><li><strong>Write a caption</strong> — Add the copy you want to appear with the post.</li><li><strong>Choose destinations</strong> — Select which connected platforms the clip should go to.</li><li><strong>Publish or schedule</strong> — Publish now, or pick a date and time to post later.</li></ol><p>You can also save a post as a draft while a clip is still being made, then come back to attach the clip and finish scheduling.</p><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><p>You can publish your clips directly to:</p><ul><li><strong>YouTube Shorts</strong></li><li><strong>LinkedIn</strong></li></ul><p>Additional destinations are on the way and appear in the app marked <strong>&quot;Coming soon&quot;</strong> while they finish rolling out:</p><ul><li><strong>TikTok</strong></li><li><strong>Instagram</strong></li><li><strong>Threads</strong></li></ul><p>Each platform appears as a destination card. For an available platform, connect your account from the destinations area and select it as a destination when you publish; if a connection ever needs renewing, the card will prompt you to reconnect. Platforms still rolling out show as &quot;Coming soon&quot; until they&#39;re ready for your account.</p><h2 id="the-social-calendar" tabindex="-1">The Social Calendar <a class="header-anchor" href="#the-social-calendar" aria-label="Permalink to &quot;The Social Calendar&quot;">​</a></h2><p>Scheduled and draft posts appear on the Social Publishing calendar, which you can view by month or by week. This gives you a clear picture of what&#39;s going out and when, so you can keep a steady cadence of social content alongside your episode publishing schedule. Recent clips and recently published posts are also surfaced so you can reuse or follow up on them quickly.</p><h2 id="how-to-use-social-publishing-effectively" tabindex="-1">How to Use Social Publishing Effectively <a class="header-anchor" href="#how-to-use-social-publishing-effectively" aria-label="Permalink to &quot;How to Use Social Publishing Effectively&quot;">​</a></h2><h3 id="lead-with-your-strongest-moments" tabindex="-1">Lead With Your Strongest Moments <a class="header-anchor" href="#lead-with-your-strongest-moments" aria-label="Permalink to &quot;Lead With Your Strongest Moments&quot;">​</a></h3><p>Let PodSEO surface the highlights, then pick the clips that best represent what makes your show worth listening to. A single compelling moment often travels further than a longer, less focused segment.</p><h3 id="tailor-captions-to-each-audience" tabindex="-1">Tailor Captions to Each Audience <a class="header-anchor" href="#tailor-captions-to-each-audience" aria-label="Permalink to &quot;Tailor Captions to Each Audience&quot;">​</a></h3><p>Write captions that give viewers a reason to watch and a clear next step — like listening to the full episode. A strong caption paired with a great clip is what turns a casual viewer into a new listener.</p><h3 id="build-a-posting-rhythm" tabindex="-1">Build a Posting Rhythm <a class="header-anchor" href="#build-a-posting-rhythm" aria-label="Permalink to &quot;Build a Posting Rhythm&quot;">​</a></h3><p>Use the calendar to schedule clips in advance rather than posting sporadically. Consistency helps your content perform better over time and keeps your show visible between episodes.</p><h3 id="repurpose-across-platforms" tabindex="-1">Repurpose Across Platforms <a class="header-anchor" href="#repurpose-across-platforms" aria-label="Permalink to &quot;Repurpose Across Platforms&quot;">​</a></h3><p>The same clip can reach different audiences on different platforms. Publishing one strong clip to several connected destinations is an efficient way to maximize the reach of every episode.</p><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><ul><li><strong><a href="/features/planner.html">Planner</a></strong> — Social Publishing lives alongside the Board, Calendar, and AI Producer, so clip creation fits naturally into your episode workflow</li><li><strong><a href="/features/pulse.html">Pulse</a></strong> — Timely episodes inspired by trending topics make especially shareable clips</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Social Publishing is available within the Planner. Free accounts include a limited amount of clip creation each month, with finished videos carrying a watermark. Paid plans remove the watermark and unlock more monthly clips, and some destinations are available only on paid plans.</p><hr><h3 id="pro-tips" tabindex="-1">Pro Tips <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;Pro Tips&quot;">​</a></h3><ul><li>Confirm you have the rights to an episode&#39;s audio before creating clips from it</li><li>Generate a clip again with a different background or style if the first version doesn&#39;t feel on-brand</li><li>Save drafts early — you can write captions and choose destinations even before a clip is fully ready</li><li>Schedule clips around your episode releases so each new episode gets a promotional push</li></ul><p>Social Publishing turns the work you&#39;ve already done into shareable video, helping every episode reach beyond your podcast feed and bring new listeners back to your show.</p>',44)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
